<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLButtonAttributes } from 'svelte/elements'; import { composeEventHandlers } from '../shared/events.js'; import { getPopoverContext } from '../popover/popover-context.svelte.js'; import { getNavigationMenuContext, getNavigationMenuItemContext } from './navigation-menu-context.svelte.js'; export interface Props extends Omit<HTMLButtonAttributes, 'children'> { children?: Snippet; delay?: number; ref?: HTMLButtonElement | null; } let { children, delay = 50, ref = $bindable(null), onclick, onpointerenter, ...rest }: Props = $props(); const navigation = getNavigationMenuContext(); const item = getNavigationMenuItemContext(); const popover = getPopoverContext(); let timer: ReturnType<typeof setTimeout>; let open = $derived(navigation.value === item.value); function activate(event: Event) { navigation.setValue(open ? null : item.value, event); popover.trigger = ref; }</script><button bind:this={ref} {...rest} id={item.triggerId} type="button" aria-expanded={open} aria-controls={item.contentId} data-open={open ? '' : undefined} onclick={composeEventHandlers(onclick, activate)} onpointerenter={composeEventHandlers(onpointerenter, (event) => { clearTimeout(timer); timer = setTimeout(() => { navigation.setValue(item.value, event); popover.trigger = ref; }, delay); })}>{@render children?.()}</button>
